// Cross-check the static registration scan against the repository's
// authoritative tool catalog (docs/tool-catalog.md, generated by booting each
// tool plugin). A tool the catalog knows but the scan misses is an extractor gap.
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { dataDir, repoRoot } from './paths.mjs'

const root = repoRoot()
const { records, unresolved } = JSON.parse(readFileSync(join(dataDir(), 'registrations.json'), 'utf8'))

let catalogTools
try {
  catalogTools = new Map()
  const catalog = readFileSync(join(root, 'docs', 'tool-catalog.md'), 'utf8')
  for (const line of catalog.split('\n')) {
    const match = line.match(/^\|\s*`(@deepseek-ai\/dsh-[^`]+)`\s*\|\s*(.+?)\s*\|/)
    if (match === null) continue
    const packageName = match[1].replace('@deepseek-ai/dsh-', '')
    catalogTools.set(packageName, [...match[2].matchAll(/`([^`]+)`/g)].map(item => item[1]))
  }
} catch {
  throw new Error(`dsh-learn: cannot read the tool catalog at ${join(root, 'docs', 'tool-catalog.md')}`)
}

const scannedTools = new Map()
for (const record of records.filter(item => item.kind === 'tool')) {
  if (!scannedTools.has(record.package)) scannedTools.set(record.package, new Set())
  scannedTools.get(record.package).add(record.name)
}

console.log(`catalog tool packages: ${catalogTools.size}`)
console.log(`scanned tool packages: ${scannedTools.size}`)
console.log(`dynamic registration sites: ${unresolved.length}`)

const findings = []
for (const [pkg, names] of catalogTools) {
  const scanned = scannedTools.get(pkg)
  if (scanned === undefined) {
    findings.push({ kind: 'missing-package', pkg, message: `MISSING PACKAGE ${pkg}: ${names.join(', ')}` })
    continue
  }
  const missing = names.filter(name => !scanned.has(name))
  if (missing.length > 0) {
    findings.push({
      kind: 'name-gap',
      pkg,
      message: `NAME GAP ${pkg}: catalog-only ${missing.join(', ')} | scanned ${[...scanned].join(', ')}`,
    })
  }
}
for (const pkg of scannedTools.keys()) {
  if (!catalogTools.has(pkg)) {
    findings.push({ kind: 'not-in-catalog', pkg, message: `NOT IN CATALOG ${pkg}: ${[...scannedTools.get(pkg)].join(', ')}` })
  }
}

// Expected divergences between a static scan and a boot-derived catalog. Each
// is a real property of the code, not a tolerated bug; anything else is a gap.
const EXPECTED = [
  {
    reason: 'transport owned by the tool registry, not registered from package source',
    matches: ({ kind, pkg }) => kind === 'missing-package' && pkg === 'tools',
  },
  {
    reason: 'MCP tool definitions generated at runtime from server capabilities',
    matches: ({ kind, pkg }) => kind === 'missing-package' && pkg === 'experimental-browser-use-stagehand-native',
  },
  {
    reason: 'delegation name is the load-time `toolName` config; the scan resolves only its default',
    matches: ({ kind, pkg }) => kind === 'name-gap' && pkg === 'tool-subagent',
  },
  {
    reason: 'provides a non-product tool surface; the catalog covers shipped product tools',
    matches: ({ kind, pkg }) => kind === 'not-in-catalog'
      && (pkg === 'cua' || pkg === 'experimental-computer-use-cua-driver-native'),
  },
]

for (const finding of findings) {
  const expected = EXPECTED.find(rule => rule.matches(finding))
  console.log(`${expected ? 'EXPECTED' : 'UNEXPECTED'}  ${finding.message}`)
  if (expected !== undefined) console.log(`            (${expected.reason})`)
  else process.exitCode = 1
}
if (findings.length === 0) console.log('OK: scan and catalog agree')
